SELECT track_name, artist_name, released_year, streams FROM public.spotify
WHERE streams IS NOT NULL
ORDER BY streams DESC, track_name, artist_name LIMIT 5;

SELECT released_year, COUNT(*) AS songs,
ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (), 2) AS pct_of_dataset
FROM public.spotify GROUP BY released_year ORDER BY released_year;

SELECT column_name, data_type FROM information_schema.columns
WHERE table_schema='public' AND table_name='spotify' AND column_name ILIKE '%duration%'
ORDER BY column_name;

SELECT track_name, artist_name, in_spotify_playlists FROM public.spotify
WHERE in_spotify_playlists = (SELECT MAX(in_spotify_playlists) FROM public.spotify)
ORDER BY track_name, artist_name;

WITH top_tracks AS (SELECT danceability_pct FROM public.spotify WHERE streams IS NOT NULL
ORDER BY streams DESC, track_name, artist_name LIMIT 15)
SELECT COUNT(*) AS tracks, ROUND(AVG(danceability_pct),2) AS avg_danceability FROM top_tracks;

SELECT CASE WHEN in_apple_playlists IS NULL THEN 'unknown' WHEN in_apple_playlists > 0 THEN 'present' ELSE 'absent' END AS playlist_presence,
COUNT(*) AS tracks, ROUND(AVG(valence_pct),2) AS avg_valence FROM public.spotify
GROUP BY 1 ORDER BY 1;

SELECT released_month, COUNT(*) AS tracks, COUNT(*) FILTER (WHERE in_deezer_charts>0) AS charted_tracks,
ROUND(100.0 * COUNT(*) FILTER (WHERE in_deezer_charts>0) / NULLIF(COUNT(in_deezer_charts),0),2) AS charted_pct,
ROUND(AVG(in_deezer_charts),2) AS avg_chart_count FROM public.spotify GROUP BY released_month ORDER BY released_month;

SELECT released_year, key, COUNT(*) AS tracks,
ROUND(100.0*COUNT(*)/SUM(COUNT(*)) OVER (PARTITION BY released_year),2) AS pct_within_year
FROM public.spotify GROUP BY released_year,key ORDER BY released_year,key NULLS LAST;

SELECT track_name, artist_name, streams, in_spotify_charts, in_apple_charts, in_deezer_charts, in_shazam_charts
FROM public.spotify WHERE in_spotify_charts>0 AND in_apple_charts>0 AND in_deezer_charts>0 AND in_shazam_charts>0
ORDER BY streams DESC NULLS LAST,track_name,artist_name;

WITH d AS (SELECT EXTRACT(ISODOW FROM MAKE_DATE(released_year,released_month,released_day))::int AS iso_weekday, (in_spotify_charts > 0 OR in_apple_charts > 0 OR in_deezer_charts > 0 OR in_shazam_charts > 0) AS charted FROM public.spotify)
SELECT iso_weekday, COUNT(*) AS tracks, COUNT(*) FILTER (WHERE charted) AS charted_tracks,
ROUND(100.0*COUNT(*) FILTER (WHERE charted)/COUNT(*),2) AS charted_pct FROM d GROUP BY iso_weekday ORDER BY iso_weekday;

WITH k AS (SELECT key, COUNT(*) AS tracks, COUNT(streams) AS known_stream_tracks, AVG(streams) AS mean_streams, SUM(streams) AS total_streams FROM public.spotify WHERE key IS NOT NULL GROUP BY key)
SELECT DENSE_RANK() OVER (ORDER BY mean_streams DESC NULLS LAST) AS popularity_rank, key, tracks, known_stream_tracks, ROUND(mean_streams,2) AS avg_streams, total_streams
FROM k ORDER BY popularity_rank,key;
